sp_widget.client_script:
api.controller=function($scope) {
  /* widget controller */
  var c = this;

	// Estado inicial (pode ser null, true ou false)
$scope.isLowercase = null;

// Escuta evento do rootScope para atualizar o estado
$scope.$root.$on('toggleCaseEvent', function(event, isLowercase) {
  $scope.isLowercase = isLowercase;
});

};

sp_widget.css:
.sobre-nos-widget {
    font-family: 'Roboto Flex', sans-serif;
    color: #293273;
    //max-width: 1200px;
    margin: 5rem auto;
    padding: 0 20px;
    display: flex;
    flex-wrap: wrap;
    gap: 2rem;
    align-items: center;
    justify-content: space-between;
    background: white;
}

div, h1, h2, h3, h4, span, figcaption, p, a{
	 font-family: 'Roboto Flex', sans-serif;
}

.titulo-superior {
   margin-top: 5rem;
  flex-basis: 100%;      /* ocupa toda largura do flex container */
  font-family: 'Roboto Flex', sans-serif;
  font-size: 3.4rem;
  font-weight: 600;
  color: #293273;
  margin-bottom: 2rem;
  text-align: center; /* ou left */
  padding: 10px;
}



.sobre-nos-texto {
    flex: 1 1 500px;
  	margin-left: 2rem;
}

.sobre-nos-titulo {
    font-size: 1.5rem;
    font-weight: 600;
    color: #6CB4EE;
    text-transform: uppercase;
    margin-bottom: 0.5rem;
}

.sobre-nos-headline {
    font-size: 3rem;
    font-weight: 700;
    line-height: 1.3;
    color: #293273;
    margin-bottom: 1rem;
}

.sobre-nos-descricao {
    font-size: 1.5rem;
    color: #444;
    line-height: 1.6;
    margin-bottom: 2rem;
    font-weight: 300;
}

.sobre-nos-info-container {
    display: flex;
    flex-wrap: wrap;
    gap: 2rem;
}

.sobre-nos-contato,
.sobre-nos-redes {
    flex: 1;
    min-width: 220px;
}

.sobre-nos-contato h4,
.sobre-nos-redes h4 {
    font-size: 1.1rem;
    color: #6CB4EE;
    font-weight: 600;
    margin-bottom: 0.5rem;
    text-transform: uppercase;
}

.sobre-nos-contato span,
.sobre-nos-redes span {
    font-size: 1.1rem;
    color: #6CB4EE;
    font-weight: 600;
    margin-bottom: 0.5rem;
    text-transform: uppercase;
}

.sobre-nos-contato p,
.sobre-nos-contato a {
    font-size: 1.5rem;
    color: #293273;
    margin: 0.3rem 0;
    text-decoration: none;
    font-weight: 300;
}

.sobre-nos-redes {
    display: flex;
    flex-direction: column;
    align-items: flex-end;
}

.sobre-nos-redes h4 {
    text-align: right;
}

.sobre-nos-redes .icon-container {
    display: flex;
    gap: 12px;
    align-items: center;
    justify-content: flex-end;
}

.sobre-nos-redes .icon-container a {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 36px;
    height: 36px;
    border: 2px solid #293273;
    border-radius: 8px;
    font-size: 16px;
    color: #293273;
    text-decoration: none;
    transition: background-color 0.3s, color 0.3s;
}

.sobre-nos-redes .icon-container a:hover {
    background-color: #293273;
    color: white;
}

.sobre-nos-img {
    flex: 1 1 400px;
    max-width: 708px;
}

.sobre-nos-img img {
    width: 100%;
    max-width: 708px;
    height: auto;
    object-fit: cover;
}

.imagem-legenda {
    font-size: 8px;
    color: #555;
    margin-top: 8px;
    max-width: 708px;
    margin-left: auto;
    margin-right: auto;
    line-height: 1.4;
}

.lowercase-text {
    text-transform: lowercase;
}

.uppercase-text {
    text-transform: uppercase;
}

/* Responsividade */
@media (max-width: 1024px) {
    .sobre-nos-widget {
        flex-direction: column;
        text-align: center;
    }

    .sobre-nos-info-container {
        justify-content: center;
        text-align: center;
    }

    .sobre-nos-redes {
        align-items: center;
    }

    .sobre-nos-redes h4 {
        text-align: center;
    }

    .sobre-nos-redes .icon-container {
        justify-content: center;
    }
}

@media (max-width: 500px) {
    .sobre-nos-headline {
        font-size: 2rem;
    }

  .titulo-superior {
  	margin-top: 25rem;
  }

    .sobre-nos-descricao {
        font-size: 1.2rem;
    }

    .sobre-nos-contato p,
    .sobre-nos-contato a {
        font-size: 1.2rem;
    }
}
